        if hasattr(obj, '_data') and hasattr(obj._data, 'isna'):
            return obj._constructor(obj._data.isna())
        else:
            raise AttributeError(f"Object {obj} does not have a '_data' attribute with 'isna' method")
    elif isinstance(obj, list):
        return _isna_ndarraylike_old(np.asarray(obj, dtype=object))
